<?php
declare(strict_types=1);require_once __DIR__.'/access.php';require_role('admin');$pdo=db();$message=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$values=['company_name'=>trim((string)$_POST['company_name']),'working_days_mode'=>(string)$_POST['working_days_mode'],'holidays'=>json_encode(array_values(array_filter(array_map('trim',preg_split('/[\r\n,]+/',(string)$_POST['holidays']))))), 'expense_categories'=>json_encode(array_values(array_filter(array_map('trim',preg_split('/[\r\n,]+/',(string)$_POST['expense_categories']))))), 'smtp_host'=>trim((string)$_POST['smtp_host']),'smtp_port'=>trim((string)$_POST['smtp_port']),'smtp_username'=>trim((string)$_POST['smtp_username']),'smtp_password'=>(string)$_POST['smtp_password'],'smtp_from'=>trim((string)$_POST['smtp_from'])];$save=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($values as $key=>$value)$save->execute([$key,$value]);$message='Settings saved.';}
$settings=[];foreach($pdo->query('SELECT setting_key,setting_value FROM settings') as $row)$settings[$row['setting_key']]=$row['setting_value'];$holidays=implode("\n",json_decode($settings['holidays']??'[]',true)?:[]);$categories=implode("\n",json_decode($settings['expense_categories']??'[]',true)?:[]);function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><title>Company Settings</title><link rel="stylesheet" href="assets/css/saas.css"></head><body class="saas-body"><div class="saas-shell"><aside class="saas-sidebar"><div class="brand"><span>MT</span> Mega Techzy</div><a class="saas-nav" href="admin_dashboard.php">▦ <span>Overview</span></a><a class="saas-nav active" href="company_settings.php">⚙ <span>Settings</span></a><a class="saas-nav" href="backup_export.php">⇩ <span>Backup</span></a><a class="saas-nav" href="logout.php">↪ <span>Log out</span></a></aside><main class="saas-main"><h1 class="saas-title">Company Settings</h1><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><form method="post" class="saas-card"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Company name<input class="form-control" name="company_name" value="<?=e($settings['company_name']??'MT Mega Techzy')?>"></label><label>Working days mode<select class="form-control" name="working_days_mode"><option value="weekdays">Weekdays (Mon-Fri)</option><option value="calendar">Calendar days</option></select></label><label>Holidays, one per line<textarea class="form-control" name="holidays"><?=e($holidays)?></textarea></label><label>Expense categories, one per line<textarea class="form-control" name="expense_categories"><?=e($categories)?></textarea></label><h2>SMTP</h2><input class="form-control" name="smtp_host" placeholder="SMTP host" value="<?=e($settings['smtp_host']??'')?>"><input class="form-control" name="smtp_port" placeholder="Port" value="<?=e($settings['smtp_port']??'')?>"><input class="form-control" name="smtp_username" placeholder="Username" value="<?=e($settings['smtp_username']??'')?>"><input class="form-control" type="password" name="smtp_password" placeholder="Password" value="<?=e($settings['smtp_password']??'')?>"><input class="form-control" name="smtp_from" placeholder="From email" value="<?=e($settings['smtp_from']??'')?>"><button class="btn-indigo">Save settings</button></form></main></div></body></html>
